package com.cryptostrategy.platform.persistence.api;import com.cryptostrategy.platform.leaderboard.api.port.out.LeaderboardStore;import com.cryptostrategy.platform.persistence.internal.leaderboard.JdbcLeaderboardStore;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import javax.sql.DataSource;import java.util.Objects;public final class LeaderboardPersistenceFactory{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public LeaderboardPersistenceFactory(DataSource source){Objects.requireNonNull(source);jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));}public LeaderboardStore createStore(){return new JdbcLeaderboardStore(jdbc,tx);}}
